namespace Astronomy.MediaFactory.Core.DocumentaryBlueprint;
public sealed class DocumentaryMediaPipelineSummarizer
{
 public DocumentaryMediaPipelineSummary Summarize(DocumentaryMediaPipelineExecutionRecord r){ArgumentNullException.ThrowIfNull(r);var done=r.VariantRecords.Where(x=>x.Status==DocumentaryMediaPipelineStatus.Complete).ToArray();return new(r.ExecutionId,r.MediaProjectId,r.TopicId,r.MediaProject.TopicProfile.TopicFamily,r.Status,r.VariantCount,r.CompletedVariantCount,r.FailedVariantCount,done.Count(x=>x.VariantType is DocumentaryMediaVariantType.LongEnglish or DocumentaryMediaVariantType.LongHindi),done.Count(x=>x.VariantType is DocumentaryMediaVariantType.ShortEnglish or DocumentaryMediaVariantType.ShortHindi),done.Count(x=>x.VariantType is DocumentaryMediaVariantType.LongEnglish or DocumentaryMediaVariantType.ShortEnglish),done.Count(x=>x.VariantType is DocumentaryMediaVariantType.LongHindi or DocumentaryMediaVariantType.ShortHindi),r.AssetCount,r.ExecutionPlan.AssetPlans.Count(x=>(int)x.AssetType<=5),r.ExecutionPlan.AssetPlans.Count(x=>x.AssetType==DocumentaryMediaAssetType.NarrationAudio),r.ExecutionPlan.AssetPlans.Count(x=>x.AssetType==DocumentaryMediaAssetType.SubtitleDocument),r.ExecutionPlan.AssetPlans.Count(x=>x.AssetType==DocumentaryMediaAssetType.SceneVideo),r.ExecutionPlan.AssetPlans.Count(x=>x.AssetType==DocumentaryMediaAssetType.VariantVideo),r.PlannedDurationMilliseconds,r.EffectiveDurationMilliseconds,r.Metadata.CreatedUtc,r.Metadata.CreatedBy,r.IsComplete);}
}
